from pathlib import Path
import json,numpy as np
R=Path(__file__).resolve().parents[1];A=R/'artifacts/bilin18_tensor_decomposition';stem='bilin18_l17_joint_input_regression';j=json.loads((A/f'{stem}.json').read_text());z=np.load(A/f'{stem}_rows.npz');e=z['errors'];d=z['effects'];assert e.shape==(6,9,24,96,2) and np.isfinite(e).all() and all(j['numerical_gates'].values());rec=1-e.sum((2,3))/d.sum((0,1))
def contrast(r,sp):return np.array([r[4,0]-r[2,0],(r[4,1+sp]-r[2,1+sp]).mean(),r[4,0]-r[1,0],(r[4,1+sp]-r[1,1+sp]).mean()])
